-- READ-ONLY only. Run this query with Weather MCP execute_sql once per selected database:
-- loucka_reconstruction, old_weewx, weewx_WH1080, and (when accepted by MCP) each dotted pocasi-loucka.eu database.
-- Counts cover strict open intervals between adjacent reconstruction endpoints (dateTime > start AND dateTime < end).
-- Per-gap source row counts do not establish timestamp/value concordance, operational uptime, or restoration eligibility.

SELECT 1 AS gap_id, 2009 AS reconstruction_endpoint_year, 1248189300 AS gap_start_epoch, 1248436800 AS gap_end_epoch, COUNT(*) AS source_rows, MIN(dateTime) AS first_source_time, MAX(dateTime) AS last_source_time, COALESCE(SUM(outTemp IS NOT NULL),0) AS outTemp_nonnull, COALESCE(SUM(outTemp=0),0) AS outTemp_zero, COALESCE(SUM(outHumidity IS NOT NULL),0) AS outHumidity_nonnull, COALESCE(SUM(rain IS NOT NULL),0) AS rain_nonnull, COALESCE(SUM(rainRate IS NOT NULL),0) AS rainRate_nonnull, COALESCE(SUM(windSpeed IS NOT NULL),0) AS windSpeed_nonnull, COALESCE(SUM(windGust IS NOT NULL),0) AS windGust_nonnull, COALESCE(SUM(usUnits IS NOT NULL),0) AS usUnits_nonnull, COALESCE(SUM(`interval` IS NOT NULL),0) AS interval_nonnull FROM archive WHERE dateTime > 1248189300 AND dateTime < 1248436800
UNION ALL
